    tr = "".join("<tr>" + "".join(f'<td{" style=font-family:Inter,sans-serif" if i == len(r)-1 else ""}>{c}</td>' for i, c in enumerate(r)) + "</tr>" for r in rows)
    return f'<div class="table-scroll bg-surface-container-low"><table class="data"><caption class="vh">{cap}</caption><thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table></div>'
